# Capstone integration for Week 1: refuse or escalate
from main import probabilities

ALLOWED    = {'PLANE', 'CAR'}
BLOCKED    = {'UNICORN'}
MARGIN_MIN = 0.25

def decide(labels, logits, temperature=1.0):
    p = probabilities(logits, temperature)
    order = sorted(range(len(p)), key=lambda i: -p[i])
    top1, top2 = order[0], order[1]
    margin = p[top1] - p[top2]
    label  = labels[top1]
    if label in BLOCKED:
        return {'action': 'REFUSE',   'label': label, 'margin': margin}
    if margin < MARGIN_MIN:
        return {'action': 'ESCALATE', 'label': label, 'margin': margin}
    if label not in ALLOWED:
        return {'action': 'ESCALATE', 'label': label, 'margin': margin}
    return {'action': 'ACT',           'label': label, 'margin': margin}

import unittest
from capstone_guard import decide

BLOCKED_ROW = (['UNICORN','PLANE','CAR'], [3, 2, 1])
THIN_ROW    = (['PLANE','CAR','UNICORN'], [2.0, 1.9, 0.5])
CLEAN_ROW   = (['PLANE','CAR','UNICORN'], [3, 1, 0])

class CapstoneGuard(unittest.TestCase):
    def test_A_blocked_wins_refuse(self):
        self.assertEqual(decide(*BLOCKED_ROW, 1.0)['action'], 'REFUSE')

    def test_B_low_T_still_refuses_blocked(self):
        # cold sampling does NOT rescue a BLOCKED top-1
        self.assertEqual(decide(*BLOCKED_ROW, 1.0)['action'], 'REFUSE')
        self.assertEqual(decide(*BLOCKED_ROW, 0.1)['action'], 'REFUSE')

    def test_C_thin_margin_escalates(self):
        # margin < MARGIN_MIN
        self.assertEqual(decide(*THIN_ROW, 1.0)['action'], 'ESCALATE')

    def test_D_clean_allowed_acts(self):
        self.assertEqual(decide(*CLEAN_ROW, 1.0)['action'], 'ACT')

    def test_E_invalid_temperature_propagates(self):
        with self.assertRaises(ValueError):
            decide(*CLEAN_ROW, 0)

if __name__ == '__main__':
    unittest.main()

